package config

import (
	api "github.com/MateusMoutinhoOrg/Keep/sandbox/api"
)

// NewConfig builds Sandbox.Config out of what AgnosConfig/project.yaml
// declared when this file was rendered, so nothing has to parse that file to
// know which project it is running as.
// Generated by `agnos build` — do not edit by hand.
func NewConfig(sandbox *api.Sandbox) api.Config {
	return api.Config{
		ProjectName: "Keep",
		Version:     "v0.1.0",
	}
}
